// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


public interface ServerInterface {
    
    /**
     * Wait for the next incoming session request.
     *
     * Returns `None` once the endpoint is closed.
     */
    suspend fun `accept`(): SessionRequest?
    
    /**
     * Close all connections.
     */
    fun `close`(`code`: kotlin.ULong = 0uL, `reason`: kotlin.String = "")
    
    /**
     * The local `(host, port)` the server is bound to.
     */
    fun `localAddr`(): RemoteAddress
    
    /**
     * Replace the TLS certificate for new incoming connections.
     */
    fun `reloadCertificates`(`certificateChain`: List<kotlin.ByteArray>, `privateKey`: kotlin.ByteArray)
    
    /**
     * Wait for all connections to shut down cleanly.
     */
    suspend fun `waitClosed`()
    
    companion object
}

