            FfiConverterOptionalSequenceByteArray.write(value.`serverCertificateHashes`, buf)
            FfiConverterBoolean.write(value.`noCertVerification`, buf)
            FfiConverterTypeCongestionControl.write(value.`congestionControl`, buf)
            FfiConverterOptionalDouble.write(value.`maxIdleTimeoutSecs`, buf)
            FfiConverterOptionalDouble.write(value.`keepAliveIntervalSecs`, buf)
    }
}



