/**
 * Server configuration record.
 *
 * `certificate_chain` is a list of DER-encoded certs (leaf first), and
 * `private_key` is the DER-encoded private key. `bind` accepts any address
 * quinn understands, e.g. `"[::]:4433"` or `"0.0.0.0:4433"`.
 */
data class ServerConfig (
    var `certificateChain`: List<kotlin.ByteArray>
    , 
    var `privateKey`: kotlin.ByteArray
    , 
    var `bind`: kotlin.String = "[::]:4433" 
    , 
    var `congestionControl`: CongestionControl
    , 
    var `maxIdleTimeoutSecs`: kotlin.Double? = 30.0 
    , 
    var `keepAliveIntervalSecs`: kotlin.Double? = null 
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeServerConfig: FfiConverterRustBuffer<ServerConfig> {
    override fun read(buf: ByteBuffer): ServerConfig {
        return ServerConfig(
            FfiConverterSequenceByteArray.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterString.read(buf),
            FfiConverterTypeCongestionControl.read(buf),
            FfiConverterOptionalDouble.read(buf),
            FfiConverterOptionalDouble.read(buf),
        )
    }

    override fun allocationSize(value: ServerConfig) = (
            FfiConverterSequenceByteArray.allocationSize(value.`certificateChain`) +
            FfiConverterByteArray.allocationSize(value.`privateKey`) +
            FfiConverterString.allocationSize(value.`bind`) +
            FfiConverterTypeCongestionControl.allocationSize(value.`congestionControl`) +
            FfiConverterOptionalDouble.allocationSize(value.`maxIdleTimeoutSecs`) +
            FfiConverterOptionalDouble.allocationSize(value.`keepAliveIntervalSecs`)
    )

    override fun write(value: ServerConfig, buf: ByteBuffer) {
            FfiConverterSequenceByteArray.write(value.`certificateChain`, buf)
            FfiConverterByteArray.write(value.`privateKey`, buf)
            FfiConverterString.write(value.`bind`, buf)
            FfiConverterTypeCongestionControl.write(value.`congestionControl`, buf)
            FfiConverterOptionalDouble.write(value.`maxIdleTimeoutSecs`, buf)
            FfiConverterOptionalDouble.write(value.`keepAliveIntervalSecs`, buf)
    }
}



