 */

enum class CongestionControl {
    
    DEFAULT,
    THROUGHPUT,
    LOW_LATENCY;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCongestionControl: FfiConverterRustBuffer<CongestionControl> {
    override fun read(buf: ByteBuffer) = try {
        CongestionControl.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CongestionControl) = 4UL

    override fun write(value: CongestionControl, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
