/**
 * Error returned by all UniFFI-exported functions.
 */
sealed class WebTransportException: kotlin.Exception() {
    
    class Connect(
        
        val v1: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SessionRejected(
        
        val `statusCode`: kotlin.UShort, 
        
        val `detail`: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "statusCode=${ `statusCode` }, detail=${ `detail` }"
    }
    
    class SessionClosedByPeer(
        
        val `closedBy`: kotlin.String, 
        
        val `code`: kotlin.ULong?, 
        
        val `reason`: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "closedBy=${ `closedBy` }, code=${ `code` }, reason=${ `reason` }"
    }
    
    class SessionClosedLocally(
        ) : WebTransportException() {
        override val message
            get() = ""
    }
    
    class SessionTimeout(
        ) : WebTransportException() {
        override val message
            get() = ""
    }
    
    class Protocol(
        
        val v1: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class StreamClosedByPeer(
        
        val `kind`: kotlin.String, 
        
        val `code`: kotlin.UInt
        ) : WebTransportException() {
        override val message
            get() = "kind=${ `kind` }, code=${ `code` }"
    }
    
    class StreamClosedLocally(
        ) : WebTransportException() {
        override val message
            get() = ""
    }
    
    class StreamTooLong(
        
        val `limit`: kotlin.ULong
        ) : WebTransportException() {
        override val message
            get() = "limit=${ `limit` }"
    }
    
    class StreamIncompleteRead(
        
        val `expected`: kotlin.ULong, 
        
        val `got`: kotlin.ULong, 
        
        val `partial`: kotlin.ByteArray
        ) : WebTransportException() {
        override val message
            get() = "expected=${ `expected` }, got=${ `got` }, partial=${ `partial` }"
    }
    
    class DatagramTooLarge(
        ) : WebTransportException() {
        override val message
            get() = ""
    }
    
    class DatagramNotSupported(
        
        val `reason`: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidArgument(
        
        val v1: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Io(
        
        val v1: kotlin.String
        ) : WebTransportException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Cancelled(
        ) : WebTransportException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WebTransportException> {
        override fun lift(error_buf: RustBuffer.ByValue): WebTransportException = FfiConverterTypeWebTransportError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeWebTransportError : FfiConverterRustBuffer<WebTransportException> {
    override fun read(buf: ByteBuffer): WebTransportException {
        

        return when(buf.getInt()) {
            1 -> WebTransportException.Connect(
                FfiConverterString.read(buf),
                )
            2 -> WebTransportException.SessionRejected(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> WebTransportException.SessionClosedByPeer(
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> WebTransportException.SessionClosedLocally()
            5 -> WebTransportException.SessionTimeout()
            6 -> WebTransportException.Protocol(
                FfiConverterString.read(buf),
                )
            7 -> WebTransportException.StreamClosedByPeer(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            8 -> WebTransportException.StreamClosedLocally()
            9 -> WebTransportException.StreamTooLong(
                FfiConverterULong.read(buf),
                )
            10 -> WebTransportException.StreamIncompleteRead(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterByteArray.read(buf),
                )
            11 -> WebTransportException.DatagramTooLarge()
            12 -> WebTransportException.DatagramNotSupported(
                FfiConverterString.read(buf),
                )
            13 -> WebTransportException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            14 -> WebTransportException.Io(
                FfiConverterString.read(buf),
                )
            15 -> WebTransportException.Cancelled()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WebTransportException): ULong {
        return when(value) {
            is WebTransportException.Connect -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is WebTransportException.SessionRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`statusCode`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is WebTransportException.SessionClosedByPeer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`closedBy`)
                + FfiConverterOptionalULong.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is WebTransportException.SessionClosedLocally -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WebTransportException.SessionTimeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WebTransportException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is WebTransportException.StreamClosedByPeer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`kind`)
                + FfiConverterUInt.allocationSize(value.`code`)
            )
            is WebTransportException.StreamClosedLocally -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WebTransportException.StreamTooLong -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`limit`)
            )
            is WebTransportException.StreamIncompleteRead -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`expected`)
                + FfiConverterULong.allocationSize(value.`got`)
                + FfiConverterByteArray.allocationSize(value.`partial`)
            )
            is WebTransportException.DatagramTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WebTransportException.DatagramNotSupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is WebTransportException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is WebTransportException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is WebTransportException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: WebTransportException, buf: ByteBuffer) {
        when(value) {
            is WebTransportException.Connect -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is WebTransportException.SessionRejected -> {
                buf.putInt(2)
                FfiConverterUShort.write(value.`statusCode`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is WebTransportException.SessionClosedByPeer -> {
                buf.putInt(3)
                FfiConverterString.write(value.`closedBy`, buf)
                FfiConverterOptionalULong.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is WebTransportException.SessionClosedLocally -> {
                buf.putInt(4)
                Unit
            }
            is WebTransportException.SessionTimeout -> {
                buf.putInt(5)
                Unit
            }
            is WebTransportException.Protocol -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is WebTransportException.StreamClosedByPeer -> {
                buf.putInt(7)
                FfiConverterString.write(value.`kind`, buf)
                FfiConverterUInt.write(value.`code`, buf)
                Unit
            }
            is WebTransportException.StreamClosedLocally -> {
                buf.putInt(8)
                Unit
            }
            is WebTransportException.StreamTooLong -> {
                buf.putInt(9)
                FfiConverterULong.write(value.`limit`, buf)
                Unit
            }
            is WebTransportException.StreamIncompleteRead -> {
                buf.putInt(10)
                FfiConverterULong.write(value.`expected`, buf)
                FfiConverterULong.write(value.`got`, buf)
                FfiConverterByteArray.write(value.`partial`, buf)
                Unit
            }
            is WebTransportException.DatagramTooLarge -> {
                buf.putInt(11)
                Unit
            }
            is WebTransportException.DatagramNotSupported -> {
                buf.putInt(12)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is WebTransportException.InvalidArgument -> {
                buf.putInt(13)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is WebTransportException.Io -> {
                buf.putInt(14)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is WebTransportException.Cancelled -> {
                buf.putInt(15)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




